# FINAL SOLUTION - Implement complete transform
test_input = grids['Test input']
bg = 8
h, w = len(test_input), len(test_input[0])

# Find components with non-8 connectivity
visited = [[False]*w for _ in range(h)]
components = []

for r in range(h):
    for c in range(w):
        if test_input[r][c] != bg and not visited[r][c]:
            comp_pixels = [(r, c)]
            queue = [(r, c)]
            visited[r][c] = True

            while queue:
                cr, cc = queue.pop(0)
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < h and 0 <= nc < w and not visited[nr][nc]:
                        if test_input[nr][nc] != bg:
                            visited[nr][nc] = True
                            comp_pixels.append((nr, nc))
                            queue.append((nr, nc))

            rvals = [r for r, c in comp_pixels]
            cvals = [c for r, c in comp_pixels]
            min_r, max_r = min(rvals), max(rvals)
            min_c, max_c = min(cvals), max(cvals)

            components.append({
                'min_r': min_r, 'max_r': max_r,
                'min_c': min_c, 'max_c': max_c,
            })

print(f"Found {len(components)} components")

result = [row[:] for row in test_input]

def transform_row(row_data):
    """Duplicate left half of row"""
    half = len(row_data) // 2
    return list(row_data[:half]) + list(row_data[:half])

def process_component(comp):
    min_r, max_r = comp['min_r'], comp['max_r']
    min_c, max_c = comp['min_c'], comp['max_c']

    bbox_h = max_r - min_r + 1
    bbox_w = max_c - min_c + 1

    # Step 1: Find consecutive content rows from top
    seed_rows = []
    for i in range(bbox_h):
        row_data = test_input[min_r+i][min_c:max_c+1]
        has_content = any(x not in [bg, 0] for x in row_data)
        if has_content:
            seed_rows.append(row_data)
        else:
            break

    print(f"\nComponent bbox: ({min_r}-{max_r})x({min_c}-{max_c}), size {bbox_h}x{bbox_w}")
    print(f"Seed rows found: {len(seed_rows)}")
    for i, sr in enumerate(seed_rows):
        print(f"  Seed {i}: {sr}")

    # Step 2: Transform seed rows
    transformed_patterns = [transform_row(sr) for sr in seed_rows]
    print("Transformed patterns:")
    for i, tp in enumerate(transformed_patterns):
        print(f"  Pattern {i}: {tp}")

    # Step 3: Tile patterns cyclically
    result_rows = []
    for i in range(bbox_h):
        pat_idx = i % len(transformed_patterns) if transformed_patterns else 0
        result_rows.append(transformed_patterns[pat_idx][:])

    # Place into global result
    for i in range(len(result_rows)):
        final_r = min_r + i
        for j in range(bbox_w):
            result[final_r][min_c + j] = result_rows[i][j]

for comp in components:
    process_component(comp)

